const parallaxStyle = {
  parallax: {
    height: "auto",
    overflow: "hidden",
    position: "relative",
    backgroundPosition: "center center",
    backgroundSize: "cover",
    margin: "0",
    padding: "96px 0 64px",
    border: "0",
    display: "flex",
    alignItems: "center",
    backgroundColor: "#fff"
  },
  filter: {
    "&:before": {
      background: "rgba(255, 255, 255, 0.9)"
    },
    "&:after,&:before": {
      position: "absolute",
      zIndex: "1",
      width: "100%",
      height: "100%",
      display: "block",
      left: "0",
      top: "0",
      content: "''"
    }
  },
  small: {
    height: "380px"
  }
};

export default parallaxStyle;



