import { container, title, primaryColor, lightColor2 } from "assets/jss/next-genius.jsx";

const landingPageStyle = {
  container: {
    zIndex: "2",
    color: "#111827",
    ...container,
    paddingLeft: "25px"
  },
  title: {
    ...title,
    display: "inline-block",
    position: "relative",
    marginTop: "30px",
    minHeight: "32px",
    paddingBottom: "12px",
    color: "#111827",
    textDecoration: "none"
  },
  subtitle: {
    fontSize: "1.125rem",
    maxWidth: "560px",
    margin: "10px auto 0",
    color: "#6b7280"
  },
  main: {
    background: "#f9fafb",
    position: "relative",
    zIndex: "3"
  },
  mainRaised: {
    margin: "0",
    borderRadius: "0",
    boxShadow: "none",
    "@media (max-width: 576px)": {
      margin: "0",
    },
  },
  playVideo:{
    zIndex:"1"
  },
  icons:{
    fontSize:"4rem",
    color: primaryColor,
    marginTop: "-10px"
  },
  arrowGrid: {
    textAlign: "center"
  }
};

export default landingPageStyle;



